<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class GoodsReceipt extends Model {protected $fillable=['receipt_number','purchase_order_id','supplier_id','received_at','received_by','status','notes']; protected $casts=['received_at'=>'datetime']; public function purchaseOrder():BelongsTo{return $this->belongsTo(PurchaseOrder::class);} public function supplier():BelongsTo{return $this->belongsTo(Supplier::class);} public function items():HasMany{return $this->hasMany(GoodsReceiptItem::class);} }
